const baseUrl = pm.variables
    .replaceIn("{{base_url}}")
    .replace(/\/$/, "");

const username = pm.variables.get("username");
const password = pm.variables.get("password");
const loginChannel =
    pm.variables.get("loginChannel") ||
    pm.variables.get("login_channel") ||
    "WEB";

if (!baseUrl) {
    throw new Error("base_url 변수가 없습니다.");
}

if (!username) {
    throw new Error("username 변수가 없습니다.");
}

if (password === undefined || password === null) {
    throw new Error("password 변수가 없습니다.");
}

if (!["WEB", "AGENT"].includes(loginChannel)) {
    throw new Error("loginChannel은 WEB 또는 AGENT여야 합니다.");
}

function decodeBase64(value) {
    const normalized = value.replace(/\s/g, "");
    const binary = atob(normalized);
    const result = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i += 1) {
        result[i] = binary.charCodeAt(i);
    }

    return result;
}

function encodeBase64(value) {
    const bytes = value instanceof Uint8Array
        ? value
        : new Uint8Array(value);

    let binary = "";
    const chunkSize = 0x8000;

    for (let offset = 0; offset < bytes.length; offset += chunkSize) {
        const chunk = bytes.subarray(
            offset,
            Math.min(offset + chunkSize, bytes.length)
        );

        binary += String.fromCharCode(...chunk);
    }

    return btoa(binary);
}

const challengeResponse = await pm.sendRequest({
    url: `${baseUrl}/api/v1/auth/login/challenge`,
    method: "GET",
    header: {
        Accept: "application/json",
        "Cache-Control": "no-store"
    }
});

if (challengeResponse.code !== 200) {
    throw new Error(
        `Challenge 발급 실패: ${challengeResponse.code} ${challengeResponse.text()}`
    );
}

const challenge = challengeResponse.json();

if (challenge.algorithm !== "RSA-OAEP-256+A256GCM") {
    throw new Error(
        `지원하지 않는 암호화 알고리즘입니다: ${challenge.algorithm}`
    );
}

if (
    !challenge.challengeId ||
    !challenge.nonce ||
    !challenge.keyId ||
    !challenge.publicKey
) {
    throw new Error("Challenge 응답 필드가 올바르지 않습니다.");
}

const rsaPublicKey = await crypto.subtle.importKey(
    "spki",
    decodeBase64(challenge.publicKey.replace(/-----[^-]+-----/g, "")),
    {
        name: "RSA-OAEP",
        hash: "SHA-256"
    },
    false,
    ["encrypt"]
);

const aesKey = await crypto.subtle.generateKey(
    {
        name: "AES-GCM",
        length: 256
    },
    true,
    ["encrypt"]
);

const rawAesKey = await crypto.subtle.exportKey("raw", aesKey);
const iv = crypto.getRandomValues(new Uint8Array(12));

const loginPayload = {
    username,
    password,
    loginChannel,
    challengeId: challenge.challengeId,
    nonce: challenge.nonce,
    issuedAt: Date.now()
};

const plaintext = new TextEncoder().encode(JSON.stringify(loginPayload));

const ciphertext = await crypto.subtle.encrypt(
    {
        name: "AES-GCM",
        iv,
        tagLength: 128
    },
    aesKey,
    plaintext
);

const encryptedKey = await crypto.subtle.encrypt(
    {
        name: "RSA-OAEP"
    },
    rsaPublicKey,
    rawAesKey
);

const encryptedLoginBody = {
    challengeId: challenge.challengeId,
    keyId: challenge.keyId,
    encryptedKey: encodeBase64(encryptedKey),
    iv: encodeBase64(iv),
    ciphertext: encodeBase64(ciphertext)
};

pm.environment.set("encChallengeId", encryptedLoginBody.challengeId);
pm.environment.set("encKeyId", encryptedLoginBody.keyId);
pm.environment.set("encEncryptedKey", encryptedLoginBody.encryptedKey);
pm.environment.set("encIv", encryptedLoginBody.iv);
pm.environment.set("encCiphertext", encryptedLoginBody.ciphertext);

console.log("encrypted login body generated:", {
    challengeId: encryptedLoginBody.challengeId,
    keyId: encryptedLoginBody.keyId,
    encryptedKeyLength: encryptedLoginBody.encryptedKey.length,
    iv: encryptedLoginBody.iv,
    ciphertextLength: encryptedLoginBody.ciphertext.length
});

pm.request.headers.upsert({
    key: "Content-Type",
    value: "application/json"
});

pm.request.body.update(JSON.stringify(encryptedLoginBody));

console.log("actual encrypted login body:", encryptedLoginBody);
